<?php
namespace App\Controller;
use App\Entity\{Expense,Stations};use App\Service\UserAccessService;use Doctrine\ORM\EntityManagerInterface;use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;use Symfony\Component\HttpFoundation\{JsonResponse,Request};use Symfony\Component\Routing\Attribute\Route;
#[Route('/api/expenses')]final class ExpenseController extends AbstractController { #[Route('',methods:['GET'])]public function index(Request $r,EntityManagerInterface $em,UserAccessService $a):JsonResponse{if($d=$a->require([UserAccessService::ROLE_GERANT,UserAccessService::ROLE_ASSISTANT]))return$d;$station=$em->getRepository(Stations::class)->find((int)$r->query->get('station'));if(!$station||!$a->canAccessStation($station))return$a->denyStation();$rows=$em->getRepository(Expense::class)->findBy(['station'=>$station],['expenseDate'=>'DESC','id'=>'DESC']);return$this->json(['expenses'=>array_map(fn(Expense $x)=>$this->row($x),$rows)]);} #[Route('',methods:['POST'])]public function create(Request $r,EntityManagerInterface $em,UserAccessService $a):JsonResponse{if($d=$a->require([UserAccessService::ROLE_GERANT,UserAccessService::ROLE_ASSISTANT]))return$d;$v=$r->toArray();$station=$em->getRepository(Stations::class)->find((int)($v['stationId']??0));$amount=max(0,(float)($v['amount']??0));$description=trim((string)($v['description']??''));if(!$station||!$a->canAccessStation($station))return$a->denyStation();if(!$a->currentUser()||$amount<=0||$description==='')return$this->json(['message'=>'Description et montant obligatoires'],422);$x=(new Expense())->setStation($station)->setPerformedBy($a->currentUser())->setCategory(trim((string)($v['category']??''))?:'Autre')->setDescription($description)->setAmount((string)$amount)->setExpenseDate(new \DateTimeImmutable($v['date']??'today'))->setPaymentMethod(trim((string)($v['paymentMethod']??''))?:'CASH')->setReference(trim((string)($v['reference']??''))?:null)->setCreatedAt(new \DateTimeImmutable());$em->persist($x);$em->flush();return$this->json($this->row($x),201);}private function row(Expense $x):array{return['id'=>$x->getId(),'date'=>$x->getExpenseDate()?->format('Y-m-d'),'category'=>$x->getCategory(),'description'=>$x->getDescription(),'amount'=>(float)$x->getAmount(),'method'=>$x->getPaymentMethod(),'reference'=>$x->getReference(),'performedBy'=>$this->name($x->getPerformedBy())];}private function name($u):?string{return $u?trim($u->getFirstName().' '.$u->getLastName()):null;} }
